int main(int argc, char** argv) {
    auto commandLine = makeCommandLine();
    std::vector<std::string> arguments;
    arguments.reserve(argc > 1 ? static_cast<std::size_t>(argc - 1) : 0);
    for (int index = 1; index < argc; ++index) arguments.emplace_back(argv[index]);
    for (const auto& argument : arguments) {
        if (argument == "--package-path" || argument.rfind("--package-path=", 0) == 0) {
            std::cerr << "simp: --package-path is no longer supported; use -M/--module-dir\n";
            return 2;
        }
    }
    try {
        commandLine.parse(arguments);
    } catch (const std::invalid_argument& error) {
        std::cerr << "simp: " << error.what() << '\n' << commandLine.helpText();
        return 2;
    }
    if (commandLine.action() == simp::CommandLineAction::Help) {
        std::cout << commandLine.helpText();
        return 0;
    }
    if (commandLine.action() == simp::CommandLineAction::Version) {
        std::cout << commandLine.versionText();
        return 0;
    }

    bool traceParser = false;
    bool traceScanner = false;
    bool dump = false;
    bool dumpSymbols = false;
    for (const auto& target : commandLine.values("trace")) {
        std::string normalized = target;
        std::transform(normalized.begin(), normalized.end(), normalized.begin(),
                       [](unsigned char character) {
                           return static_cast<char>(std::tolower(character));
                       });
        if (normalized == "parser") traceParser = true;
        else if (normalized == "scanner") traceScanner = true;
        else if (normalized == "ast") dump = true;
        else if (normalized == "symbols") dumpSymbols = true;
        else {
            std::cerr << "simp: unsupported trace target: " << target
                      << " (expected scanner, parser, ast, or symbols)\n"
                      << commandLine.helpText();
            return 2;
        }
    }
    const bool checkOnly = commandLine.switchValue("check-only");
    const bool compileOnly = commandLine.switchValue("compile-only");
    const bool debug = commandLine.switchValue("debug");
    const bool printPaths = commandLine.switchValue("print-paths");
    std::size_t verbosity = commandLine.count("verbose");
    if (const auto verbosityValue = commandLine.value("verbosity")) {
        if (verbosity != 0) {
            std::cerr << "simp: -v and --verbosity cannot be used together\n";
            return 2;
        }
        try {
            verbosity = parseNonNegativeInteger(*verbosityValue, "--verbosity");
        } catch (const std::invalid_argument& error) {
            std::cerr << "simp: " << error.what() << '\n' << commandLine.helpText();
            return 2;
        }
    }
    if (verbosity > maximumVerbosity) {
        std::cerr << "simp: verbosity level " << verbosity << " exceeds the maximum of "
                  << maximumVerbosity << '\n';
        return 2;
    }
    const bool verbose = verbosity >= phaseVerbosity;
    std::size_t maximumIncludeDepth = 0;
    try {
        maximumIncludeDepth = parseNonNegativeInteger(
            *commandLine.value("max-include-depth"), "--max-include-depth");
    } catch (const std::invalid_argument& error) {
        std::cerr << "simp: " << error.what() << '\n' << commandLine.helpText();
        return 2;
    }
    const auto& positionalValues = commandLine.positionalValues();
    if (positionalValues.empty() && !printPaths) {
        std::cerr << "simp: required argument not found: input\n" << commandLine.helpText();
        return 2;
    }
    const auto requestedOutput = commandLine.value("output").value_or("");
    const auto irOutput = commandLine.value("emit-llvm").value_or("");
    std::vector<std::string> sourcePaths;
    std::vector<std::string> objectPaths;
    for (const auto& path : positionalValues) {
        const auto extension = std::filesystem::path(path).extension().string();
        if (extension == ".simp") sourcePaths.push_back(path);
        else if (extension == ".o" || extension == ".obj") objectPaths.push_back(path);
        else {
            std::cerr << "simp: unsupported input file type: " << path
                      << " (expected .simp, .o, or .obj)\n";
            return 2;
        }
        std::ifstream input(path, std::ios::binary);
        if (!input) {
            std::cerr << "simp: cannot open input file: " << path << '\n';
            return 2;
        }
    }
    const auto& libraryPaths = commandLine.values("library-path");
    const auto& libraries = commandLine.values("library");
    if (compileOnly && !objectPaths.empty()) {
        std::cerr << "simp: -c accepts source inputs only; object files are link inputs\n";
        return 2;
    }
    if (compileOnly && (!libraryPaths.empty() || !libraries.empty())) {
        std::cerr << "simp: -L and -l cannot be used with -c\n";
        return 2;
    }
    if (checkOnly && sourcePaths.size() != positionalValues.size()) {
        std::cerr << "simp: --check-only accepts source inputs only\n";
        return 2;
    }
    if (checkOnly && compileOnly) {
        std::cerr << "simp: --check-only cannot be used with -c\n";
        return 2;
    }
    if (checkOnly && (!requestedOutput.empty() || !irOutput.empty())) {
        std::cerr << "simp: output options cannot be used with --check-only\n";
        return 2;
    }
    if (checkOnly && (!libraryPaths.empty() || !libraries.empty())) {
        std::cerr << "simp: -L and -l cannot be used with --check-only\n";
        return 2;
    }
    if (compileOnly && sourcePaths.empty()) {
        std::cerr << "simp: -c requires at least one .simp source input\n";
        return 2;
    }
    if (sourcePaths.empty() && !irOutput.empty()) {
        std::cerr << "simp: --emit-llvm requires at least one .simp source input\n";
        return 2;
    }
    for (const auto& library : libraries) {
        if (library.empty() || library.front() == '-') {
            std::cerr << "simp: -l requires a library name without the -l prefix\n";
            return 2;
        }
    }
    std::vector<std::filesystem::path> includeSearchPaths;
    includeSearchPaths.reserve(commandLine.values("path").size());
    for (const auto& path : commandLine.values("path")) {
        includeSearchPaths.emplace_back(path);
    }

    simp::ResourcePaths resources;
    simp::ModuleSearchPaths moduleSearchPaths;
    try {
        resources = simp::resolveResourcePaths(
            simp::currentExecutablePath(argc > 0 ? argv[0] : ""),
            simp::configuredInstallLayout(), simp::processEnvironment);
        simp::ModuleSearchRequest moduleRequest;
        moduleRequest.moduleDirectoryOption = commandLine.value("module-dir");
        moduleRequest.sourcePaths = sourcePaths;
        moduleRequest.currentDirectory = std::filesystem::current_path();
        moduleSearchPaths = simp::resolveModuleSearchPaths(moduleRequest, resources,
                                                           simp::processEnvironment);
    } catch (const std::exception& error) {
        std::cerr << "simp: " << error.what() << '\n';
        return 1;
    }
    if (printPaths) {
        writeResolvedPaths(std::cout, "", resources, moduleSearchPaths);
        return 0;
    }
    if (verbosity >= pathVerbosity) {
        writeResolvedPaths(std::cerr, "[paths] ", resources, moduleSearchPaths);
    }
    BuildContext buildContext;
    buildContext.compiler = compilerExecutable().path;
    buildContext.includeDirectory = resources.includeDirectory.path;
    buildContext.runtimeLibrary = resources.runtimeLibrary;
    buildContext.verbosity = verbosity;

    std::vector<std::string> temporaryPaths;
    try {
        simp::validateModuleSearchPaths(moduleSearchPaths);
        std::optional<PhaseTimer> frontendTimer;
        frontendTimer.emplace(verbosity, "parse source inputs");
        simp::Program program;
        for (const auto& inputPath : sourcePaths) {
            std::ifstream input(inputPath, std::ios::binary);
            if (!input) {
                std::cerr << "simp: cannot open input file: " << inputPath << '\n';
                return 2;
            }
            const std::string source((std::istreambuf_iterator<char>(input)),
                                     std::istreambuf_iterator<char>());
            std::unordered_set<std::string> includedFiles;
            std::error_code pathError;
            const auto canonicalInput = std::filesystem::canonical(inputPath, pathError);
            if (pathError) {
                std::cerr << "simp: cannot resolve input file: " << inputPath << '\n';
                return 2;
            }
            includedFiles.insert(canonicalInput.string());
            auto tokens = simp::tokenizeWithIncludes(
                source, inputPath, includedFiles, 0, true, maximumIncludeDepth, {},
                includeSearchPaths);
            if (traceScanner) traceTokens(tokens, std::cerr);
            tokens.push_back({simp::TokenType::End, "", {inputPath, 1, 1}});
            if (verbose) {
                std::cerr << "[verbose] lexed " << (tokens.size() - 1)
                          << " tokens from " << inputPath << '\n';
            }
            simp::Parser parser(std::move(tokens), traceParser ? &std::cerr : nullptr);
            auto unit = parser.parseProgram(false);
            if (unit.hasStart) {
                if (program.hasStart) {
                    throw simp::DiagnosticError(
                        unit.location,
                        "input files contain more than one top-level 'start' block");
                }
                program.hasStart = true;
                program.location = unit.location;
                program.statements = std::move(unit.statements);
            }
            program.imports.insert(program.imports.end(),
                                   std::make_move_iterator(unit.imports.begin()),
                                   std::make_move_iterator(unit.imports.end()));
            program.namespaces.insert(program.namespaces.end(),
                                      std::make_move_iterator(unit.namespaces.begin()),
                                      std::make_move_iterator(unit.namespaces.end()));
            program.classes.insert(program.classes.end(),
                                   std::make_move_iterator(unit.classes.begin()),
                                   std::make_move_iterator(unit.classes.end()));
            program.outOfLineMethods.insert(
                program.outOfLineMethods.end(),
                std::make_move_iterator(unit.outOfLineMethods.begin()),
                std::make_move_iterator(unit.outOfLineMethods.end()));
        }
        if (!sourcePaths.empty() && !program.hasStart) {
            throw simp::DiagnosticError(
                {sourcePaths.front(), 1, 1},
                "programs must contain exactly one top-level 'start' block");
        }
        frontendTimer.emplace(verbosity, "load imported modules");
        simp::ModuleLoadOptions moduleOptions;
        moduleOptions.packageSearchRoots = moduleSearchPaths.packageRoots();
        moduleOptions.projectLockFile = moduleSearchPaths.projectLockFile.path;
        const auto moduleLoad = simp::loadImportedModules(program, moduleOptions);
        if (verbose && moduleLoad.versionPolicyActive) {
            for (const auto& module : moduleLoad.modules) {
                std::cerr << "[verbose] selected module " << module.name << '@'
                          << module.version << " from " << module.sourcePath << '\n';
            }
        }
        frontendTimer.emplace(verbosity, "semantic analysis");
        simp::SemanticAnalyzer semanticAnalyzer;
        semanticAnalyzer.setBuiltinSource(resources.builtinSource);
        semanticAnalyzer.analyze(program);
        frontendTimer.reset();
        if (dump) {
            simp::dumpAst(program, std::cout);
        }
        if (dumpSymbols) {
            semanticAnalyzer.dumpSymbolTable(std::cout);
        }
        if (checkOnly) {
            if (verbose) {
                std::cerr << "[verbose] semantic analysis succeeded; code generation skipped\n";
            }
            return 0;
        }

        const auto defaultOutput = compileOnly
                                       ? (sourcePaths.empty()
                                              ? std::string("a.o")
                                              : (std::filesystem::path(".") /
                                                 (std::filesystem::path(
                                                      sourcePaths.front())
                                                      .stem()
                                                      .string() +
                                                  ".o"))
                                                    .string())
                                       : (sourcePaths.empty()
                                              ? std::string("a.out")
                                              : defaultExecutablePath(sourcePaths.front()));
        const auto outputPath = requestedOutput.empty() ? defaultOutput : requestedOutput;
        if (!irOutput.empty()) {
            for (const auto& inputPath : positionalValues) {
                if (samePath(irOutput, inputPath)) {
                    throw std::invalid_argument(
                        "--emit-llvm output must not overwrite an input file");
                }
            }
            if (samePath(irOutput, outputPath)) {
                throw std::invalid_argument(
                    "--emit-llvm and -o must name different output files");
            }
        }
        for (const auto& inputPath : positionalValues) {
            if (samePath(outputPath, inputPath)) {
                throw std::invalid_argument("-o must not overwrite an input file");
            }
        }
        std::optional<PhaseTimer> backendTimer;
        backendTimer.emplace(verbosity, "generate LLVM IR");
        simp::CodeGenerator codeGenerator(SIMP_TARGET_TRIPLE, debug);
        std::unordered_map<std::string, std::string> inlineShims;
        std::vector<std::string> irPaths;
        if (!sourcePaths.empty()) {
            const auto ir = codeGenerator.generate(program);
            for (const auto& shim : codeGenerator.inlineShims()) {
                inlineShims.emplace(shim.first, shim.second);
            }
            const auto irPath = irOutput.empty()
                                    ? temporaryPath(outputPath, "main.ll")
                                    : irOutput;
            if (irOutput.empty()) temporaryPaths.push_back(irPath);
            else ensureOutputDirectory(irOutput);
            writeFile(irPath, ir);
            irPaths.push_back(irPath);
            for (const auto& module : moduleLoad.modules) {
                simp::CodeGenerator moduleGenerator(SIMP_TARGET_TRIPLE, debug);
                const auto moduleIr = moduleGenerator.generate(program, module.name);
                for (const auto& shim : moduleGenerator.inlineShims()) {
                    inlineShims.emplace(shim.first, shim.second);
                }
                const auto moduleIrPath =
                    temporaryPath(outputPath, "module." +
                                                  std::to_string(irPaths.size()) + ".ll");
                writeFile(moduleIrPath, moduleIr);
                temporaryPaths.push_back(moduleIrPath);
                irPaths.push_back(moduleIrPath);
            }
        }
        std::string inlineShimPath;
        if (!inlineShims.empty()) {
            inlineShimPath = temporaryPath(outputPath, "inline.c");
            // Keep the legacy capture ABI available; Stdlib.h is the public C API.
            std::string source =
                "#include \"simp/Stdlib.h\"\n"
                "#include \"simp/RuntimeGc.h\"\n"
                "#include <stdlib.h>\n#include <stdio.h>\n#include <string.h>\n"
                "#include <errno.h>\n#include <ctype.h>\n#include <stdint.h>\n"
                "#include <limits.h>\n#include <unistd.h>\n\n";
            for (const auto& shim : inlineShims) {
                source += shim.second;
                source += '\n';
            }
            writeFile(inlineShimPath, source);
            temporaryPaths.push_back(inlineShimPath);
        }
        LinkInputs packageInputs;
        for (const auto& path : moduleLoad.libraryPaths) {
            appendUnique(packageInputs.libraryPaths, path.string());
        }
        for (const auto& library : moduleLoad.libraries) {
            appendUnique(packageInputs.libraries, library);
        }
        if (!inlineShimPath.empty()) {
            requireResource(buildContext.includeDirectory / "simp" / "Stdlib.h",
                            "public standard-library header", "SIMP_INCLUDE_DIR");
            requireResource(buildContext.includeDirectory / "simp" / "RuntimeGc.h",
                            "runtime header", "SIMP_INCLUDE_DIR");
        }
        if (!compileOnly) {
            requireResource(buildContext.runtimeLibrary, "runtime library",
                            "SIMP_RUNTIME_DIR");
        }
        backendTimer.emplace(verbosity, compileOnly ? "compile object with clang"
                                                    : "compile and link with clang");
        int buildResult = 0;
        if (compileOnly) {
            buildResult = buildObject(buildContext, irPaths, inlineShimPath, outputPath, temporaryPaths, debug);
            if (buildResult == 0) writeLinkSidecar(outputPath, packageInputs);
        } else {
            const auto sidecarInputs = readLinkSidecars(objectPaths);
            for (const auto& path : sidecarInputs.libraryPaths) {
                appendUnique(packageInputs.libraryPaths, path);
            }
            for (const auto& library : sidecarInputs.libraries) {
                appendUnique(packageInputs.libraries, library);
            }
            buildResult = buildExecutable(
                buildContext, irPaths, objectPaths, inlineShimPath, packageInputs.libraryPaths,
                packageInputs.libraries, libraryPaths, libraries, outputPath, debug);
        }
        backendTimer.reset();
        for (const auto& temporary : temporaryPaths) {
            std::error_code ignored;
            std::filesystem::remove(temporary, ignored);
        }
        if (buildResult != 0) return 1;
        if (verbose) {
            std::cerr << "[verbose] semantic analysis succeeded; "
                      << (compileOnly ? "relocatable object produced"
                                      : "inputs linked by compiler driver")
                      << '\n';
        } else if (!dump && !dumpSymbols) {
            std::cout << "simp: built " << outputPath << '\n';
        }
    } catch (const simp::DiagnosticError& diagnostic) {
        std::cerr << diagnostic.what() << '\n';
        return 1;
    } catch (const std::exception& error) {
        std::cerr << "simp: " << error.what() << '\n';
        for (const auto& temporary : temporaryPaths) {
            std::error_code ignored;
            std::filesystem::remove(temporary, ignored);
        }
        return 1;
    }
    return 0;
}
